-- NWPH OS initial schema.
--
-- Conventions
--   ids          TEXT UUIDs generated by the application.
--   timestamps   ISO-8601 UTC text (…T…Z).
--   dates        YYYY-MM-DD text, checked with date(x) = x.
--   money        INTEGER minor units (cents) + 3-letter ISO-4217 currency.
--   archival     archived_at IS NOT NULL. Business records are archived, not
--                deleted. The only hard deletes are of rows flagged is_example.
--   is_example   1 marks clearly-labelled demonstration data that can be
--                removed in bulk from Settings.
--
-- One schema serves every venture. Adding a venture adds rows, never tables.

PRAGMA foreign_keys = ON;

-- ── Identity ────────────────────────────────────────────────────────────────

CREATE TABLE users (
  id             TEXT PRIMARY KEY,
  email          TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK (length(email) BETWEEN 3 AND 254),
  display_name   TEXT NOT NULL CHECK (length(display_name) BETWEEN 1 AND 120),
  password_hash  TEXT NOT NULL,
  -- Roles are fixed in code (src/auth/permissions.ts); the check keeps the
  -- database honest if someone edits it directly.
  role           TEXT NOT NULL CHECK (role IN ('owner', 'editor', 'viewer')),
  is_active      INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL,
  last_login_at  TEXT
);

-- Only a SHA-256 of the session token is stored, so a copy of the database
-- does not yield usable session cookies.
CREATE TABLE sessions (
  token_hash    TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  csrf_token    TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  last_seen_at  TEXT NOT NULL,
  expires_at    TEXT NOT NULL,
  flash         TEXT
);
CREATE INDEX sessions_user_idx ON sessions(user_id);

-- ── Organization and stages ─────────────────────────────────────────────────

CREATE TABLE organizations (
  id                   TEXT PRIMARY KEY,
  name                 TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
  legal_name           TEXT,
  legal_status         TEXT NOT NULL DEFAULT 'unverified'
                       CHECK (legal_status IN ('unverified', 'not_established', 'in_formation', 'established', 'dissolved', 'other')),
  legal_status_detail  TEXT,
  jurisdiction         TEXT,
  registration_reference TEXT,
  headquarters         TEXT,
  description          TEXT,
  mission              TEXT,
  guiding_philosophy   TEXT,
  ownership_notes      TEXT,
  notes                TEXT,
  profile_reviewed_at  TEXT,
  onboarding_dismissed_at TEXT,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL
);

-- Development stages are rows, not an enum, so they can be renamed, reordered
-- and extended without a migration.
CREATE TABLE development_stages (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL REFERENCES organizations(id),
  name             TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 60),
  description      TEXT,
  position         INTEGER NOT NULL,
  archived_at      TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  UNIQUE (organization_id, name)
);
CREATE INDEX development_stages_org_idx ON development_stages(organization_id, position);

-- ── Ventures ────────────────────────────────────────────────────────────────

CREATE TABLE ventures (
  id                    TEXT PRIMARY KEY,
  organization_id       TEXT NOT NULL REFERENCES organizations(id),
  name                  TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
  slug                  TEXT NOT NULL UNIQUE CHECK (slug GLOB '[a-z0-9]*' AND slug NOT GLOB '*[^a-z0-9-]*'),
  short_description     TEXT,
  description           TEXT,
  category              TEXT,
  stage_id              TEXT NOT NULL REFERENCES development_stages(id),
  -- Legal status and operational status are deliberately independent of the
  -- development stage. Nothing in the application changes them as a side
  -- effect of another action.
  legal_status          TEXT NOT NULL DEFAULT 'not_established'
                        CHECK (legal_status IN ('unverified', 'not_established', 'in_formation', 'established', 'dissolved', 'other')),
  legal_status_detail   TEXT,
  operational_status    TEXT NOT NULL DEFAULT 'proposed'
                        CHECK (operational_status IN ('proposed', 'in_development', 'operational', 'paused', 'discontinued')),
  parent_relationship   TEXT,
  ownership_notes       TEXT,
  locations             TEXT,
  mission               TEXT,
  objectives            TEXT,
  target_customers      TEXT,
  products_services     TEXT,
  value_proposition     TEXT,
  market_research       TEXT,
  business_model        TEXT,
  startup_requirements  TEXT,
  capital_requirements_notes TEXT,
  funding_sources_notes TEXT,
  operating_cost_assumptions TEXT,
  revenue_assumptions   TEXT,
  dependencies_notes    TEXT,
  next_actions          TEXT,
  internal_notes        TEXT,
  -- JSON array of field names whose current value is a provisional default
  -- rather than a confirmed fact. The interface badges these fields.
  provisional_fields    TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(provisional_fields)),
  is_example            INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at           TEXT,
  created_by            TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL
);
CREATE UNIQUE INDEX ventures_org_name_idx ON ventures(organization_id, name COLLATE NOCASE);
CREATE INDEX ventures_stage_idx ON ventures(stage_id);

CREATE TABLE venture_stage_changes (
  id             TEXT PRIMARY KEY,
  venture_id     TEXT NOT NULL REFERENCES ventures(id) ON DELETE CASCADE,
  from_stage_id  TEXT REFERENCES development_stages(id),
  to_stage_id    TEXT NOT NULL REFERENCES development_stages(id),
  note           TEXT,
  changed_by     TEXT REFERENCES users(id) ON DELETE SET NULL,
  changed_at     TEXT NOT NULL
);
CREATE INDEX venture_stage_changes_venture_idx ON venture_stage_changes(venture_id, changed_at);

-- ── Projects, milestones, tasks ─────────────────────────────────────────────
-- venture_id NULL means the record belongs to the parent organization itself.

CREATE TABLE projects (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL REFERENCES organizations(id),
  venture_id       TEXT REFERENCES ventures(id),
  name             TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 160),
  description      TEXT,
  status           TEXT NOT NULL DEFAULT 'planned'
                   CHECK (status IN ('planned', 'active', 'on_hold', 'completed', 'cancelled')),
  owner_name       TEXT,
  start_date       TEXT CHECK (start_date IS NULL OR date(start_date) = start_date),
  target_date      TEXT CHECK (target_date IS NULL OR date(target_date) = target_date),
  completed_on     TEXT CHECK (completed_on IS NULL OR date(completed_on) = completed_on),
  notes            TEXT,
  is_example       INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at      TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL
);
CREATE INDEX projects_venture_idx ON projects(venture_id);

CREATE TABLE milestones (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL REFERENCES organizations(id),
  venture_id       TEXT REFERENCES ventures(id),
  project_id       TEXT REFERENCES projects(id) ON DELETE SET NULL,
  title            TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  description      TEXT,
  due_date         TEXT CHECK (due_date IS NULL OR date(due_date) = due_date),
  status           TEXT NOT NULL DEFAULT 'planned'
                   CHECK (status IN ('planned', 'in_progress', 'completed', 'cancelled')),
  completed_on     TEXT CHECK (completed_on IS NULL OR date(completed_on) = completed_on),
  notes            TEXT,
  is_example       INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at      TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  CHECK ((status = 'completed') = (completed_on IS NOT NULL))
);
CREATE INDEX milestones_venture_idx ON milestones(venture_id, due_date);
CREATE INDEX milestones_project_idx ON milestones(project_id);

CREATE TABLE tasks (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL REFERENCES organizations(id),
  venture_id       TEXT REFERENCES ventures(id),
  project_id       TEXT REFERENCES projects(id) ON DELETE SET NULL,
  milestone_id     TEXT REFERENCES milestones(id) ON DELETE SET NULL,
  title            TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  description      TEXT,
  status           TEXT NOT NULL DEFAULT 'not_started'
                   CHECK (status IN ('not_started', 'in_progress', 'blocked', 'completed', 'cancelled')),
  priority         TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'critical')),
  assignee_name    TEXT,
  start_date       TEXT CHECK (start_date IS NULL OR date(start_date) = start_date),
  due_date         TEXT CHECK (due_date IS NULL OR date(due_date) = due_date),
  completed_on     TEXT CHECK (completed_on IS NULL OR date(completed_on) = completed_on),
  notes            TEXT,
  is_example       INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at      TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  CHECK ((status = 'completed') = (completed_on IS NOT NULL))
);
CREATE INDEX tasks_venture_idx ON tasks(venture_id);
CREATE INDEX tasks_project_idx ON tasks(project_id);
CREATE INDEX tasks_status_due_idx ON tasks(status, due_date);

-- ── Governance ──────────────────────────────────────────────────────────────

CREATE TABLE decisions (
  id                   TEXT PRIMARY KEY,
  organization_id      TEXT NOT NULL REFERENCES organizations(id),
  venture_id           TEXT REFERENCES ventures(id),
  title                TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  description          TEXT,
  category             TEXT,
  proposed_on          TEXT NOT NULL CHECK (date(proposed_on) = proposed_on),
  owner_name           TEXT,
  status               TEXT NOT NULL DEFAULT 'proposed'
                       CHECK (status IN ('proposed', 'under_review', 'approved', 'rejected', 'deferred', 'superseded')),
  options_considered   TEXT,
  rationale            TEXT,
  evidence             TEXT,
  evidence_document_id TEXT REFERENCES documents(id) ON DELETE SET NULL,
  implications         TEXT,
  review_date          TEXT CHECK (review_date IS NULL OR date(review_date) = review_date),
  decided_on           TEXT CHECK (decided_on IS NULL OR date(decided_on) = decided_on),
  outcome              TEXT,
  superseded_by_id     TEXT REFERENCES decisions(id) ON DELETE SET NULL,
  notes                TEXT,
  is_example           INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at          TEXT,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL,
  -- A decision recorded as approved or rejected must say when.
  CHECK (status NOT IN ('approved', 'rejected') OR decided_on IS NOT NULL),
  CHECK (superseded_by_id IS NULL OR superseded_by_id <> id)
);
CREATE INDEX decisions_venture_idx ON decisions(venture_id);
CREATE INDEX decisions_status_idx ON decisions(status);

-- ── Documents ───────────────────────────────────────────────────────────────

CREATE TABLE documents (
  id                   TEXT PRIMARY KEY,
  organization_id      TEXT NOT NULL REFERENCES organizations(id),
  venture_id           TEXT REFERENCES ventures(id),
  project_id           TEXT REFERENCES projects(id) ON DELETE SET NULL,
  title                TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  description          TEXT,
  category             TEXT NOT NULL,
  source               TEXT,
  source_url           TEXT CHECK (source_url IS NULL OR source_url LIKE 'http://%' OR source_url LIKE 'https://%'),
  document_date        TEXT CHECK (document_date IS NULL OR date(document_date) = document_date),
  verification_status  TEXT NOT NULL DEFAULT 'unverified'
                       CHECK (verification_status IN ('unverified', 'verified', 'outdated')),
  version_label        TEXT,
  notes                TEXT,
  is_example           INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at          TEXT,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL
);
CREATE INDEX documents_venture_idx ON documents(venture_id);
CREATE INDEX documents_category_idx ON documents(category);

-- Each upload is a new version; earlier versions are kept.
CREATE TABLE document_files (
  id             TEXT PRIMARY KEY,
  document_id    TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  version_number INTEGER NOT NULL CHECK (version_number >= 1),
  original_name  TEXT NOT NULL,
  storage_key    TEXT NOT NULL UNIQUE,
  mime_type      TEXT NOT NULL,
  size_bytes     INTEGER NOT NULL CHECK (size_bytes >= 0),
  sha256         TEXT NOT NULL,
  uploaded_by    TEXT REFERENCES users(id) ON DELETE SET NULL,
  uploaded_at    TEXT NOT NULL,
  UNIQUE (document_id, version_number)
);

CREATE TABLE tags (
  id    TEXT PRIMARY KEY,
  name  TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK (length(name) BETWEEN 1 AND 40)
);

CREATE TABLE document_tags (
  document_id  TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  tag_id       TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (document_id, tag_id)
);
CREATE INDEX document_tags_tag_idx ON document_tags(tag_id);

-- Metadata search only. File contents are not indexed (see README, Known
-- limitations); the interface says so wherever search is offered.
CREATE VIRTUAL TABLE documents_fts USING fts5(
  document_id UNINDEXED, title, description, source, tags, filenames,
  tokenize = 'unicode61 remove_diacritics 2'
);

-- ── Opportunities ───────────────────────────────────────────────────────────

CREATE TABLE opportunities (
  id                        TEXT PRIMARY KEY,
  organization_id           TEXT NOT NULL REFERENCES organizations(id),
  venture_id                TEXT REFERENCES ventures(id),
  title                     TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  description               TEXT,
  category                  TEXT NOT NULL,
  source                    TEXT,
  source_url                TEXT CHECK (source_url IS NULL OR source_url LIKE 'http://%' OR source_url LIKE 'https://%'),
  issuing_organization      TEXT,
  eligibility_requirements  TEXT,
  -- Eligibility is a human judgement. Status 'eligible' (and later stages)
  -- requires a stated basis; nothing in the app infers eligibility.
  eligibility_basis         TEXT,
  geographic_scope          TEXT,
  potential_value_minor     INTEGER CHECK (potential_value_minor IS NULL OR potential_value_minor >= 0),
  currency                  TEXT NOT NULL DEFAULT 'CAD' CHECK (length(currency) = 3 AND currency = upper(currency)),
  opens_on                  TEXT CHECK (opens_on IS NULL OR date(opens_on) = opens_on),
  deadline                  TEXT CHECK (deadline IS NULL OR date(deadline) = deadline),
  status                    TEXT NOT NULL DEFAULT 'identified'
                            CHECK (status IN ('identified', 'researching', 'eligible', 'in_preparation', 'submitted', 'awarded', 'unsuccessful', 'expired', 'not_pursuing')),
  required_documents        TEXT,
  next_action               TEXT,
  notes                     TEXT,
  is_example                INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at               TEXT,
  created_at                TEXT NOT NULL,
  updated_at                TEXT NOT NULL
);
CREATE INDEX opportunities_venture_idx ON opportunities(venture_id);
CREATE INDEX opportunities_deadline_idx ON opportunities(status, deadline);

-- ── Financial planning ──────────────────────────────────────────────────────

-- Named alternative assumption sets ("Conservative", "Grant-funded"…).
-- Entries without a scenario belong to the baseline plan.
CREATE TABLE financial_scenarios (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL REFERENCES organizations(id),
  venture_id       TEXT REFERENCES ventures(id),
  name             TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
  description      TEXT,
  is_example       INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at      TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL
);

-- One table for every planning figure. Two columns keep figures from being
-- mistaken for one another:
--   basis         forecast | budget | actual     (what kind of number it is)
--   verification  unverified | verified          (actuals only)
-- Funding rows also carry funding_status, so a potential source can never be
-- read as secured. Summaries never add across basis or currency.
CREATE TABLE financial_entries (
  id                   TEXT PRIMARY KEY,
  organization_id      TEXT NOT NULL REFERENCES organizations(id),
  venture_id           TEXT REFERENCES ventures(id),
  project_id           TEXT REFERENCES projects(id) ON DELETE SET NULL,
  scenario_id          TEXT REFERENCES financial_scenarios(id) ON DELETE SET NULL,
  opportunity_id       TEXT REFERENCES opportunities(id) ON DELETE SET NULL,
  document_id          TEXT REFERENCES documents(id) ON DELETE SET NULL,
  entry_type           TEXT NOT NULL CHECK (entry_type IN
                         ('startup_cost', 'capital_expenditure', 'operating_expense', 'revenue', 'funding_requirement', 'funding')),
  basis                TEXT NOT NULL CHECK (basis IN ('forecast', 'budget', 'actual')),
  funding_status       TEXT CHECK (funding_status IS NULL OR funding_status IN ('potential', 'applied', 'committed', 'received', 'declined')),
  category             TEXT,
  description          TEXT NOT NULL CHECK (length(description) BETWEEN 1 AND 300),
  amount_minor         INTEGER NOT NULL CHECK (amount_minor >= 0),
  currency             TEXT NOT NULL DEFAULT 'CAD' CHECK (length(currency) = 3 AND currency = upper(currency)),
  period               TEXT,
  entry_date           TEXT CHECK (entry_date IS NULL OR date(entry_date) = entry_date),
  source_reference     TEXT,
  verification_status  TEXT NOT NULL DEFAULT 'unverified' CHECK (verification_status IN ('unverified', 'verified')),
  verified_by          TEXT REFERENCES users(id) ON DELETE SET NULL,
  verified_at          TEXT,
  notes                TEXT,
  is_example           INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at          TEXT,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL,
  CHECK ((entry_type = 'funding') = (funding_status IS NOT NULL)),
  -- Only received funding is an actual; everything else in the pipeline is not.
  CHECK (entry_type <> 'funding' OR (basis = 'actual') = (funding_status = 'received')),
  CHECK (entry_type <> 'funding_requirement' OR basis <> 'actual'),
  CHECK (verification_status = 'unverified' OR basis = 'actual')
);
CREATE INDEX financial_entries_venture_idx ON financial_entries(venture_id, entry_type);
CREATE INDEX financial_entries_project_idx ON financial_entries(project_id);
CREATE INDEX financial_entries_scenario_idx ON financial_entries(scenario_id);

-- ── Risks and dependencies ──────────────────────────────────────────────────

CREATE TABLE risks (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL REFERENCES organizations(id),
  venture_id       TEXT REFERENCES ventures(id),
  project_id       TEXT REFERENCES projects(id) ON DELETE SET NULL,
  title            TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  description      TEXT,
  category         TEXT,
  -- 1–5 ordinal ratings. Their product is shown as a rough planning band,
  -- never as a probability.
  likelihood       INTEGER NOT NULL CHECK (likelihood BETWEEN 1 AND 5),
  impact           INTEGER NOT NULL CHECK (impact BETWEEN 1 AND 5),
  mitigation       TEXT,
  owner_name       TEXT,
  status           TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'monitoring', 'mitigated', 'closed', 'occurred')),
  review_date      TEXT CHECK (review_date IS NULL OR date(review_date) = review_date),
  notes            TEXT,
  is_example       INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  archived_at      TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL
);
CREATE INDEX risks_venture_idx ON risks(venture_id, status);

-- "X depends on Y". Exactly one blocked item; exactly one prerequisite, which
-- is either another record or a described external condition.
CREATE TABLE dependencies (
  id                    TEXT PRIMARY KEY,
  organization_id       TEXT NOT NULL REFERENCES organizations(id),
  venture_id            TEXT REFERENCES ventures(id),
  blocked_project_id    TEXT REFERENCES projects(id) ON DELETE CASCADE,
  blocked_milestone_id  TEXT REFERENCES milestones(id) ON DELETE CASCADE,
  blocked_task_id       TEXT REFERENCES tasks(id) ON DELETE CASCADE,
  on_project_id         TEXT REFERENCES projects(id) ON DELETE CASCADE,
  on_milestone_id       TEXT REFERENCES milestones(id) ON DELETE CASCADE,
  on_task_id            TEXT REFERENCES tasks(id) ON DELETE CASCADE,
  on_decision_id        TEXT REFERENCES decisions(id) ON DELETE CASCADE,
  on_opportunity_id     TEXT REFERENCES opportunities(id) ON DELETE CASCADE,
  external_type         TEXT CHECK (external_type IS NULL OR external_type IN ('funding', 'supplier', 'approval', 'partner', 'other')),
  description           TEXT,
  status                TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved')),
  resolved_on           TEXT CHECK (resolved_on IS NULL OR date(resolved_on) = resolved_on),
  notes                 TEXT,
  is_example            INTEGER NOT NULL DEFAULT 0 CHECK (is_example IN (0, 1)),
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL,
  CHECK ((blocked_project_id IS NOT NULL) + (blocked_milestone_id IS NOT NULL) + (blocked_task_id IS NOT NULL) = 1),
  CHECK ((on_project_id IS NOT NULL) + (on_milestone_id IS NOT NULL) + (on_task_id IS NOT NULL)
         + (on_decision_id IS NOT NULL) + (on_opportunity_id IS NOT NULL) + (external_type IS NOT NULL) = 1),
  CHECK (external_type IS NULL OR length(trim(coalesce(description, ''))) > 0),
  CHECK ((status = 'resolved') = (resolved_on IS NOT NULL))
);
CREATE INDEX dependencies_blocked_task_idx ON dependencies(blocked_task_id);
CREATE INDEX dependencies_blocked_project_idx ON dependencies(blocked_project_id);
CREATE INDEX dependencies_blocked_milestone_idx ON dependencies(blocked_milestone_id);
CREATE INDEX dependencies_venture_idx ON dependencies(venture_id, status);

-- ── Activity history ────────────────────────────────────────────────────────
-- Append-only. `changes` holds {"field": [before, after]} for updates, so a
-- material change is never silently overwritten. Passwords, tokens and
-- session data are never written here.

CREATE TABLE activity_events (
  id            TEXT PRIMARY KEY,
  occurred_at   TEXT NOT NULL,
  actor_id      TEXT REFERENCES users(id) ON DELETE SET NULL,
  actor_name    TEXT,
  event_type    TEXT NOT NULL,
  entity_type   TEXT NOT NULL,
  entity_id     TEXT NOT NULL,
  venture_id    TEXT REFERENCES ventures(id) ON DELETE SET NULL,
  summary       TEXT NOT NULL,
  changes       TEXT CHECK (changes IS NULL OR json_valid(changes))
);
CREATE INDEX activity_events_time_idx ON activity_events(occurred_at DESC);
CREATE INDEX activity_events_entity_idx ON activity_events(entity_type, entity_id);
CREATE INDEX activity_events_venture_idx ON activity_events(venture_id, occurred_at DESC);
